def reset_text(lang: str) -> dict:
    from ..services.invites import ACTIVATE_TEXT

    base = ACTIVATE_TEXT[lang]
    o = RESET_OVERRIDES[lang]
    return {**base, **{k: v for k, v in o.items() if k != "err"}, "err": {**base["err"], **o["err"]}}
